#!/usr/bin/env bash
# Regenerate example.ail from a crew_scenario/1 JSON file (default: the
# crew-lab first-contact watch). With --check, fail if example.ail is stale.
set -euo pipefail
HERE=$(cd "$(dirname "$0")/.." && pwd)
SRC=${SCENARIO:-$HERE/../../examples/crew-lab/data/watch-scenario.json}
OUT=$HERE/example.ail
literal=$(jq -c . "$SRC" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g')
render() {
cat <<AIL
module sunholo/crew_core/example
import std/result (Result, Ok, Err)
import ./scenario (Scenario, decodeScenario)

-- Generated by tools/gen-example.sh from examples/crew-lab/data/watch-scenario.json.
-- Do not edit; edit the JSON and regenerate. Five specialists prepare a bubble
-- ship's crew for possible first contact.

export pure func firstContactJson() -> string
ensures { result != "" } = "${literal}"

export pure func firstContact() -> Result[Scenario, string]
ensures { match result { Ok(s) => s.captain == "captain", Err(_) => true } } = decodeScenario(firstContactJson())

test "first contact example decodes" { match firstContact() { Ok(s) => s.id == "crew-watch-v2", Err(_) => false } }
AIL
}
if [[ "${1:-}" == --check ]]; then
  diff <(render) "$OUT" >/dev/null || { echo "example.ail is stale; run packages/crew-core/tools/gen-example.sh" >&2; exit 1; }
  echo "example.ail matches $(basename "$SRC")"
else
  render > "$OUT"; echo "wrote $OUT"
fi
